INSERT INTO reports_framework_rows VALUES ('advertising',1,'広告情報',1,'{"ID":1,"製品名":"Reports.NET","キャッチフレーズ":".NET 開発環境下でのレポート作成ツールの決定版！!","商品コード":4912345678904,"売り文句":"待望の新製品","説明":"・海外製品の翻訳版ではなく、日本の帳票に要求される機能を盛り込んだ\n　帳票作成ツールとして独自に開発した製品です。\n\n・多機能デザイナーでフレシキブルな帳票設計が可能です。\n\n・ＰＯＰやチラシ等にも使える柔軟な文字装飾機能を提供します。\n\n・帳票定義は仕様公開されたXMLファイルです。デザイナーを用いない設計や、\n　独自プログラムから帳票定義を動的生成する事等が可能です。\n\n・複数種類の帳票を1度に印刷(プレビュー)が可能です。\n\n・印刷データをそのままXMLファイルに保存し、それを読み込む事が可能です。","価格":"48,000","画像1":"image1-1.jpg","画像2":"image1-2.jpg"}'::json);
INSERT INTO reports_framework_rows VALUES ('advertising',1,'広告情報',2,'{"ID":2,"製品名":"BarCode.NET","キャッチフレーズ":".NET 開発環境下でのバーコード生成ツールの決定版！!","商品コード":4923456789014,"売り文句":"大好評発売中","説明":"　BarCode.NETは、次のことを念頭において開発いたしました。\n\n１．精密なこと\n　　単なるバーコードリーダでの検査でなく、RJSのレーザーインスペクター\n　　Model L2000 というバーコード検査機にて細かくバーコードの精度を\n　　検査しております。\n\n２．用途が様々\n　　皆様が作成されるアプリケーションからGraphicsオブジェクトを渡していた\n　　だいて、BarCode.NETが、そのGraphicsオブジェクトに対してバーコードを\n　　描画する仕組みになっておりますので、様々な用途に","価格":"18,000","画像1":"image2-1.jpg","画像2":"image2-2.jpg"}'::json);
INSERT INTO reports_framework_rows VALUES ('advertising',1,'広告情報',3,'{"ID":3,"製品名":"FontTrans.NET","キャッチフレーズ":".NET 開発環境下での装飾フォント生成ツールの決定版！!","商品コード":4934567890124,"売り文句":"便利な話題作","説明":"　FontTrans.NETは、Microsoft .NET Framework上でフォントを加工した\n画像を作成するツールです。\n　フォントを物理的な大きさ(ポイント数等)で指定して描画するのではなく、\n決められた領域内に入るように拡大/縮小して描画します。\n\n　皆様がお作りになるアプリーケーションから、Graphicsオブジェクトを\n受け渡す事により、FontTrans.NETは、そのGraphicsオブジェクトに対して、\nフォントを加工した画像を描画します。\n\nこのため、簡単に様々な用途でお使い頂け","価格":"7,000","画像1":"image3-1.jpg","画像2":"image3-2.jpg"}'::json);
INSERT INTO reports_framework_rows VALUES ('advertising',1,'広告情報',4,'{"ID":4,"製品名":"Mail2DB","キャッチフレーズ":"電子メールデータを自動的にデータベースに登録！！","商品コード":4945678901234,"売り文句":"ご存知定番！","説明":"　Mail2DBは、定型的な書式の電子メールデータを、自動的にデータベース\nに登録するソフトウエアです。\n\n　 登録したデータは、直接Excelに書き出して利用することが可能です。\n\n　Mail2DBで メールの受信を行い、あらかじめ設定しておいたルールに従い、\nメールのデータをAccess2000のデータベースへ自動振分登録します。\n\n　 WEB上のアンケートフォームからの顧客自動登録や、商品の受注管理\nなどにご利用いただけます。　\n\n　 Mail2DBは、マンション販売を目的とした不動産業への導入実績","価格":"50,000","画像1":"image4-1.jpg","画像2":"image4-2.jpg"}'::json);
